'use client';

import Link from 'next/link';
import { Footer } from '@/components/footer';

type Profile = {
  name: string;
  subtitle: string;
  accent: string;
  soft: string;
  mechanismTitle: string;
  mechanism: string;
  highlightTitle: string;
  highlight: string;
  signs: string[];
  shortTerm: string[];
  longTerm: string[];
  riskTitle: string;
  risk: string;
  emergency: string;
  emergencyNote: string;
  highlightClass?: string;
};

export function SubstanceProfilePage({ profile }: { profile: Profile }) {
  const tabs = [
    ['Signs of Use', profile.signs],
    ['Short Term', profile.shortTerm],
    ['Long Term', profile.longTerm],
  ] as const;

  return (
    <>
      <div className="bg-slate-950 px-5 py-3 text-center text-sm font-semibold text-cyan-100">
        Call <a className="font-bold text-white underline underline-offset-4" href="tel:211">2-1-1</a> for local resources · Life-threatening emergencies: <a className="font-bold text-white underline underline-offset-4" href="tel:911">9-1-1</a>
      </div>
      <header className="bg-[#41cfdf] px-5 pb-10 pt-8 sm:px-8 sm:pt-12">
        <div className="mx-auto max-w-6xl rounded-3xl bg-gradient-to-br from-slate-950 via-slate-900 to-cyan-950 px-6 py-10 text-white shadow-[0_24px_38px_-20px_rgba(2,8,23,0.95)] sm:px-12 sm:py-14">
          <Link href="/education" className="font-mono text-xs font-bold uppercase tracking-[0.18em] text-cyan-200 hover:text-white">← Back to education guides</Link>
          <div className="mt-10 max-w-4xl">
            <p className="font-mono text-xs font-bold uppercase tracking-[0.24em] text-cyan-300">Substance education guide</p>
            <h1 className="mt-4 max-w-full break-words text-pretty text-5xl font-bold tracking-tight sm:text-7xl">{profile.name}</h1>
            <p className="mt-5 max-w-3xl text-pretty text-lg leading-8 text-slate-300 sm:text-xl">{profile.subtitle}</p>
          </div>
        </div>
      </header>
      <main className="min-h-screen bg-[#41cfdf]">
        <div className="mx-auto max-w-6xl space-y-8 px-5 pb-16 sm:px-8 lg:pb-20">
          <section className="grid gap-8 lg:grid-cols-[1.3fr_0.7fr]">
            <article className="rounded-3xl bg-white p-7 shadow-[0_18px_28px_-16px_rgba(2,8,23,0.75)] sm:p-10">
              <p className="mb-2 font-mono text-xs font-bold uppercase tracking-[0.22em] text-cyan-700">01 · How it works</p>
              <h2 className="mb-7 text-balance text-3xl font-bold tracking-tight text-slate-950 sm:text-4xl">{profile.mechanismTitle}</h2>
              <p className="text-base leading-7 text-slate-700">{profile.mechanism}</p>
            </article>
            <aside className={`rounded-3xl ${profile.highlightClass ?? 'bg-slate-950'} p-7 text-white shadow-[0_18px_28px_-16px_rgba(2,8,23,0.9)] sm:p-10`}>
              <p className="font-mono text-xs font-bold uppercase tracking-[0.2em] text-cyan-300">Key point</p>
              <h2 className="mt-4 text-3xl font-bold">{profile.highlightTitle}</h2>
              <p className="mt-5 leading-7 text-slate-300">{profile.highlight}</p>
            </aside>
          </section>
          <section className="rounded-3xl bg-white p-7 shadow-[0_18px_28px_-16px_rgba(2,8,23,0.75)] sm:p-10">
            <p className="mb-2 font-mono text-xs font-bold uppercase tracking-[0.22em] text-cyan-700">02 · Immediate effects</p>
            <h2 className="mb-7 text-balance text-3xl font-bold tracking-tight text-slate-950 sm:text-4xl">Recognize the effects</h2>
            <div className="grid gap-4 md:grid-cols-3">
              {tabs.map(([title, items]) => (
                <div key={title}>
                  <h3 className={`mb-4 text-xl font-black ${profile.accent}`}>{title}</h3>
                  <ul className="space-y-3 text-slate-600">{items.map((item) => <li key={item} className={`rounded-xl border border-slate-200 border-l-4 ${profile.accent.replace('text-', 'border-')} ${profile.soft} p-4 leading-6`}>{item}</li>)}</ul>
                </div>
              ))}
            </div>
          </section>
          <section className="grid gap-8 lg:grid-cols-2">
            <article className={`rounded-3xl ${profile.soft} p-7 shadow-[0_18px_28px_-16px_rgba(2,8,23,0.55)] sm:p-10`}>
              <p className={`mb-2 font-mono text-xs font-bold uppercase tracking-[0.22em] ${profile.accent}`}>03 · Long-term consequences</p>
              <h2 className="mb-7 text-balance text-3xl font-bold tracking-tight text-slate-950 sm:text-4xl">{profile.riskTitle}</h2>
              <p className="leading-7 text-slate-700">{profile.risk}</p>
            </article>
            <article className="rounded-3xl bg-red-50 p-7 shadow-[0_18px_28px_-16px_rgba(2,8,23,0.55)] sm:p-10">
              <p className="mb-2 font-mono text-xs font-bold uppercase tracking-[0.22em] text-red-700">Medical emergency</p>
              <h2 className="mb-7 text-balance text-3xl font-bold tracking-tight text-slate-950 sm:text-4xl">Identifying an emergency</h2>
              <p className="leading-7 text-slate-700">{profile.emergency}</p>
              {profile.emergencyNote && <div className="mt-6 rounded-2xl bg-red-600 p-5 font-bold leading-6 text-white">{profile.emergencyNote}</div>}
            </article>
          </section>
        </div>
      </main>
      <Footer />
    </>
  );
}

